(61, 'Real Estate Social Media PostTemplate', '<p><span data-slate-fragment=\"\" style=\"white-space: pre;\">{\n  \"canvas_specifications\": {\n    \"width_px\": 1080,\n    \"height_px\": 1080,\n    \"aspect_ratio\": \"1:1\",\n    \"resolution_dpi\": 300,\n    \"color_mode\": \"RGB\"\n  },\n  \"template_type\": \"Real Estate Social Media Flyer Template\",\n  \"target_platform\": \"Freepik Contributor Asset\",\n  \"color_scheme\": {\n    \"primary_cyan_teal\": \"#00A8B5\",\n    \"secondary_lime_yellow\": \"#E8E74D\",\n    \"accent_dark_slate\": \"#1E2A38\",\n    \"accent_white\": \"#FFFFFF\",\n    \"text_grey\": \"#5A6578\",\n    \"overlay_dark_cyan\": \"#005662\"\n  },\n  \"typography_specifications\": {\n    \"fonts_used\": [\n      {\n        \"font_family\": \"Montserrat\",\n        \"type\": \"Google Font\",\n        \"weights\": [600, 700, 800, 900]\n      },\n      {\n        \"font_family\": \"Open Sans\",\n        \"type\": \"Google Font\",\n        \"weights\": [400, 600, 700]\n      }\n    ]\n  },\n  \"top_left_header\": {\n    \"logo_group\": {\n      \"icon\": {\n        \"description\": \"Cyan circular badge with house silhouette and wave curve cutout\",\n        \"icon_glyph\": \"\\\\f015\",\n        \"color\": \"#00A8B5\"\n      },\n      \"line_1\": {\n        \"text\": \"Modern House\",\n        \"font_family\": \"Montserrat\",\n        \"font_style\": \"Bold\",\n        \"font_weight\": 700,\n        \"font_size_px\": 28,\n        \"text_color\": \"#1E2A38\"\n      },\n      \"line_2\": {\n        \"text\": \"Slogan Goes Here\",\n        \"font_family\": \"Open Sans\",\n        \"font_style\": \"Regular\",\n        \"font_weight\": 400,\n        \"font_size_px\": 16,\n        \"text_color\": \"#5A6578\"\n      }\n    }\n  },\n  \"main_headline_container\": {\n    \"shape\": \"Large circular overlay arc container in cyan (#00A8B5) with translucent blending over background house\",\n    \"position\": \"Left to Center canvas area\",\n    \"headline_group\": {\n      \"line_1\": {\n        \"text\": \"PERFECT\",\n        \"font_family\": \"Montserrat\",\n        \"font_style\": \"Bold Uppercase\",\n        \"font_weight\": 700,\n        \"font_size_px\": 68,\n        \"text_color\": \"#E8E74D\",\n        \"letter_spacing_px\": 3\n      },\n      \"line_2\": {\n        \"text\": \"HOME\",\n        \"font_family\": \"Montserrat\",\n        \"font_style\": \"Black Condensed Uppercase\",\n        \"font_weight\": 900,\n        \"font_size_px\": 116,\n        \"text_color\": \"#FFFFFF\"\n      },\n      \"line_3\": {\n        \"text\": \"FOR SALE\",\n        \"font_family\": \"Montserrat\",\n        \"font_style\": \"Black Uppercase\",\n        \"font_weight\": 900,\n        \"font_size_px\": 80,\n        \"text_color\": \"#E8E74D\"\n      },\n      \"divider_line\": \"Horizontal thick white bar beneath headline\"\n    },\n    \"sub_description\": {\n      \"text\": \"Lorem ipsum dolor sit amet, consectet adipiscing elit, sed diam.\",\n      \"font_family\": \"Open Sans\",\n      \"font_style\": \"Regular\",\n      \"font_weight\": 400,\n      \"font_size_px\": 16,\n      \"text_color\": \"#FFFFFF\",\n      \"line_height_px\": 24\n    }\n  },\n  \"cta_and_website_section\": {\n    \"position\": \"Lower-Left area (inside cyan circle container)\",\n    \"cta_button\": {\n      \"text\": \"BOOK NOW\",\n      \"font_family\": \"Montserrat\",\n      \"font_style\": \"Bold Uppercase\",\n      \"font_weight\": 700,\n      \"font_size_px\": 20,\n      \"text_color\": \"#1E2A38\",\n      \"button_shape\": \"Sharp Lime-Yellow Rectangle\",\n      \"button_color\": \"#E8E74D\"\n    },\n    \"website_url\": {\n      \"text\": \"www.website.com\",\n      \"font_family\": \"Montserrat\",\n      \"font_style\": \"SemiBold\",\n      \"font_weight\": 600,\n      \"font_size_px\": 22,\n      \"text_color\": \"#FFFFFF\"\n    }\n  },\n  \"image_frames\": [\n    {\n      \"frame_index\": 1,\n      \"type\": \"Diagonal Full House Exterior F