(563, 'Web Banner', '<p><span data-slate-fragment=\"\" style=\"white-space: pre;\">{\n  \"canvas_specifications\": {\n    \"format\": \"Horizontal Web Banner Template\",\n    \"dimensions_px\": {\n      \"width\": 1200,\n      \"height\": 628,\n      \"aspect_ratio\": \"1.91:1\"\n    },\n    \"resolution_dpi\": 300,\n    \"color_mode\": \"RGB / CMYK Compatible\",\n    \"bleed_mm\": 0\n  },\n  \"template_type\": \"Digital Marketing Agency Corporate Web Banner\",\n  \"target_platform\": \"Freepik Contributor Asset (Web Header / Social Ad Banner)\",\n  \"color_scheme\": {\n    \"primary_purple\": \"#7D64EE\",\n    \"accent_soft_purple\": \"#9A85F2\",\n    \"accent_dark_slate\": \"#2E3137\",\n    \"accent_grey\": \"#E7E9ED\",\n    \"text_dark\": \"#1E2229\",\n    \"text_body_grey\": \"#6C727F\",\n    \"text_white\": \"#FFFFFF\",\n    \"background_white\": \"#FFFFFF\"\n  },\n  \"typography_specifications\": {\n    \"fonts_used\": [\n      {\n        \"font_family\": \"Montserrat\",\n        \"weights\": [600, 700, 800, 900],\n        \"usage\": \"Main headline (\'MARKETING AGENCY\'), button labels, contact numbers\"\n      },\n      {\n        \"font_family\": \"Caveat / Great Vibes\",\n        \"weights\": [400, 700],\n        \"usage\": \"Script script kicker (\'Digital\')\"\n      },\n      {\n        \"font_family\": \"Open Sans\",\n        \"weights\": [400, 600],\n        \"usage\": \"Body descriptive text, website URL, brand slogan\"\n      }\n    ]\n  },\n  \"layout_sections\": {\n    \"header_brand_area\": {\n      \"position\": \"Top-left corner on clean white field\",\n      \"logo\": {\n        \"icon\": \"Purple hexagon/shield badge with white lightning bolt silhouette\",\n        \"brand_name\": \"LOGO HERE (Dark Slate, Bold, Uppercase)\",\n        \"tagline\": \"Your Slogan Here (Grey, Small)\"\n      }\n    },\n    \"left_content_area\": {\n      \"position\": \"Left half of the canvas\",\n      \"headline_group\": {\n        \"script_kicker\": \"Digital (Purple, Handwritten Script)\",\n        \"line_1\": \"MARKETING (Dark Slate, Extra Bold, Uppercase)\",\n        \"line_2\": \"AGENCY (Purple, Extra Bold, Uppercase)\"\n      },\n      \"body_paragraph\": \"Lorem ipsum dolor sit amet, consectetuer adipiscing elit, sed diam nonummy\",\n      \"call_to_action_row\": {\n        \"join_button\": {\n          \"shape\": \"Rounded rectangle / pill shape with soft purple drop shadow\",\n          \"fill\": \"Solid Purple (#7D64EE)\",\n          \"label\": \"Join Now (White, Semi-bold)\"\n        },\n        \"social_pill\": {\n          \"shape\": \"Horizontal purple capsule shape\",\n          \"icons\": [\"Facebook (\\\\f39e)\", \"Twitter (\\\\f099)\", \"LinkedIn (\\\\f08c)\"]\n        }\n      },\n      \"footer_contact_row\": {\n        \"phone_block\": {\n          \"icon\": \"Phone handset outline (Purple)\",\n          \"value\": \"000 123 456 789 (Dark Slate, Medium)\"\n        },\n        \"website_block\": {\n          \"icon\": \"Laptop / Desktop monitor outline (Purple)\",\n          \"value\": \"Your website here (Dark Slate, Medium)\"\n        }\n      }\n    },\n    \"right_hero_composition\": {\n      \"position\": \"Right half of the banner\",\n      \"photo_frame\": {\n        \"shape\": \"Angled geometric hexagon/chevron container mask\",\n        \"content_description\": \"Smiling businesswoman wearing glasses sitting at desk working on paperwork with laptop open\",\n        \"accent_borders\": [\n          \"Thick solid purple (#7D64EE) chevron wing extending to the upper right\",\n          \"Layered light grey (#E7E9ED) diagonal background chevron panels\",\n          \"Dark slate (#2E3137) angled triangular accent corner tab (Top-Right)\",\n          \"Thin slate grey accent chevron bar (Bottom-Right)\"\n        ]\n      }\n    }\n  }\n}</span></p>', '[]', '[]', '[\"uploads\\/task_images\\/task_6a901e048061a.webp\"]', '[]', 1, 2, 'Graphic Design', 1, 'Medium', 'Completed', 0, 'Stopped', NULL, 147775