(564, 'Modern Company Banner Design PSD Template', '', NULL, '[\"uploads/task_images/task_6a901f8340995.webp\"]', '[\"uploads\\/task_images\\/task_6a90229f3543c.webp\"]', '[]', 1, NULL, 'Graphic Design', 1, 'Medium', 'Unassigned', 0, 'Stopped', NULL, 0, '', '2026-08-27 11:30:00', '2026-08-27 11:42:26', NULL, NULL, NULL, '2026-08-27', NULL, NULL, NULL, NULL, NULL, NULL, 'agentic', '{\"task_title\":\"Modern Company Banner Design PSD Template\",\"doc_format\":\"Web Banner Set • 3 Color Variations\",\"resolution_mode\":\"72 DPI • RGB\",\"dimensions\":\"1200 x 300 px per banner\",\"bleed_margin\":\"0 px • Digital Use\",\"color_palette\":[{\"name\":\"Charcoal Navy\",\"hex\":\"#20262D\"},{\"name\":\"Banner White\",\"hex\":\"#F5F6F7\"},{\"name\":\"Modern Blue\",\"hex\":\"#159ED3\"},{\"name\":\"Blue Shadow\",\"hex\":\"#087CB5\"},{\"name\":\"Modern Gold\",\"hex\":\"#C17A00\"},{\"name\":\"Modern Red\",\"hex\":\"#E52B2F\"},{\"name\":\"Primary Text\",\"hex\":\"#20262D\"},{\"name\":\"Secondary Text\",\"hex\":\"#666B70\"}],\"typography\":[{\"font\":\"Montserrat\",\"weights\":\"400, 500, 600, 700\",\"usage\":\"Company name, Modern Banner headline, banner text and section labels\"},{\"font\":\"Open Sans\",\"weights\":\"300, 400, 600\",\"usage\":\"Supporting tagline, lorem ipsum copy and small utility text\"}],\"layout_breakdown\":[{\"section\":\"BANNER 01 — BLUE VARIATION\",\"description\":\"Wide horizontal banner with a dark charcoal left panel, white right panel and angular cyan-blue geometric divider centered between both sections.\"},{\"section\":\"BANNER 02 — GOLD VARIATION\",\"description\":\"Inverted layout with the white company-information panel on the left, dark charcoal headline panel on the right and a sharp amber-gold center chevron.\"},{\"section\":\"BANNER 03 — RED VARIATION\",\"description\":\"Dark charcoal company-information panel on the left, white headline panel on the right and a vivid red geometric center divider.\"},{\"section\":\"LEFT CONTENT BLOCK\",\"descri