ame\":\"Trim Line Margin (210x297mm)\",\"type\":\"guide\",\"icon\":\"🔲\"},{\"name\":\"Bleed Boundary (3mm All Margins)\",\"type\":\"guide\",\"icon\":\"🔲\"},{\"name\":\"Safe Zone Margin (5mm inside trim)\",\"type\":\"guide\",\"icon\":\"🔲\"},{\"name\":\"Baseline and Text Alignment Guides\",\"type\":\"guide\",\"icon\":\"🔲\"}]},{\"folder\":\"02_TEXT_CONTENT\",\"layers\":[{\"name\":\"Dream Studio Wordmark\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Visual Art & Design Descriptor\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Recipient Name and Address\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Letter Date\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Letter Body Paragraphs\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Signature Name and Job Title\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Phone Number and Contact Details\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Email, Website and Address Lines\",\"type\":\"text\",\"icon\":\"📁\"}]},{\"folder\":\"03_LOGO_&_ICONS\",\"layers\":[{\"name\":\"Dream Studio Hexagonal Logo Mark\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Contact Icon - Phone\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Contact Icon - Email\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Contact Icon - Website\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Contact Icon - Location\",\"type\":\"vector\",\"icon\":\"📁\"}]},{\"folder\":\"04_SIGNATURE_&_GRAPHICS\",\"layers\":[{\"name\":\"Managing Director Signature - Replace Here\",\"type\":\"smart_object\",\"icon\":\"🖼️\"},{\"name\":\"Signature Baseline and Name Accent\",\"type\":\"vector\",\"icon\":\"📁\"}]},{\"folder\":\"05_VECTOR_SHAPES\",\"layers\":[{\"name\":\"Top-Right Red Triangle\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Top-Right Charcoal Fold\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Top-Right Light Gray Fold\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Bottom-Left Red Triangle\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Bottom-Left Charcoal Fold\