]},{\"folder\":\"03_LOGO_&_ICONS\",\"layers\":[{\"name\":\"Hexagon Brand Mark Outer Shape\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Hexagon Brand Mark Inner Line\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Contact Phone Icon\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Contact Globe Icon\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Contact Email or Location Icon\",\"type\":\"vector\",\"icon\":\"📁\"}]},{\"folder\":\"04_SIGNATURE_ASSETS\",\"layers\":[{\"name\":\"Handwritten Signature - Replace Here\",\"type\":\"smart_object\",\"icon\":\"🖼️\"},{\"name\":\"Signature Transparency Cleanup Mask\",\"type\":\"mask\",\"icon\":\"◼️\"}]},{\"folder\":\"05_VECTOR_SHAPES\",\"layers\":[{\"name\":\"Top Navy Header Rectangle\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Cyan Header Accent Stripe\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Header Teal Gradient Transition\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Bottom Navy Diagonal Footer Block\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Bottom Cyan Footer Band\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Footer White Diagonal Divider\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Circular Contact Icon Backgrounds\",\"type\":\"shape\",\"icon\":\"🎨\"}]},{\"folder\":\"06_BACKGROUND\",\"layers\":[{\"name\":\"Paper White Base Canvas\",\"type\":\"solid_color\",\"icon\":\"🎨\"},{\"name\":\"Optional Subtle Paper Texture\",\"type\":\"smart_object\",\"icon\":\"🖼️\"}]},{\"folder\":\"07_PRINT_PREPRESS\",\"layers\":[{\"name\":\"CMYK Color Conversion Check\",\"type\":\"adjustment\",\"icon\":\"⚙️\"},{\"name\":\"Rich Black Header Output Check\",\"type\":\"adjustment\",\"icon\":\"⚙️\"},{\"name\":\"Overprint and Knockout Review\",\"type\":\"adjustment\",\"icon\":\"⚙️\"},{\"name\":\"Export Notes - PDF/X-1a\",\"type\":\"note\",\"icon\":\"📝\"}]}]}'),
(593, 'Minimal Corporate Company Profile Flyer PSD Template', '', '[]', '[\"uploads\\/task_images\\/task_6a9261de71678.webp\"]', '[]', '[\"https://www.magnific.com/free-vector/art-illustration_409136258.htm#fromView=author&page=3&position=5&uuid=9901dd1d-af31-4d42-9940-8f9678e099fe\"]', 1, NULL, 'Graphic Design', 1, 'Medium', 'Unassigned', 0, 'Stopped', NULL, 0, NULL, '2026-08-29 04:37:16', '2026-08-29 04:37:16', NULL, NULL, NULL, '2026-08-29', NULL, NULL, NULL, NULL, NULL, NULL, 'agentic', '{\"task_title\":\"Minimal Corporate Company Profile Flyer PSD Template\",\"doc_format\":\"A4 Print Flyer\",\"resolution_mode\":\"300 DPI • CMYK\",\"dimensions\":\"210 x 297 mm\",\"bleed_margin\":\"3 mm All Margins\",\"color_palette\":[{\"name\":\"Corporate Teal\",\"hex\":\"#0A9B9B\"},{\"name\":\"Deep Slate Footer\",\"hex\":\"#2C3442\"},{\"name\":\"Primary Text\",\"hex\":\"#3E4348\"},{\"name\":\"Secondary Text\",\"hex\":\"#81868B\"},{\"name\":\"Rule Line Gray\",\"hex\":\"#A7AAAC\"},{\"name\":\"Light Gray Text\",\"hex\":\"#D9DDDF\"},{\"name\":\"Background White\",\"hex\":\"#FFFFFF\"}],\"typography\":[{\"font\":\"Montserrat\",\"weights\":\"600, 700\",\"usage\":\"Company name, employee name, section labels, footer contact labels and logo tagline\"},{\"font\":\"Open Sans\",\"weights\":\"400, 600\",\"usage\":\"Corporate profile copy, address details, dates, contact information and supporting captions\"}],\"layout_breakdown\":[{\"section\":\"TOP BRAND HEADER\",\"description\":\"Clean white header with a compact circular teal-and-slate company mark positioned at the upper left, followed by COMPANY LOGO wordmark and a small corporate tagline. A thin horizontal gray divider extends across the upper-right area.\"},{\"section\":\"DOCUMENT META INFORMATION\",\"description\":\"Upper content block contains a bold recipient or employee name, muted job-title and address details, with a small right-aligned date line.\"},{\"section\":\"MAIN CORPORATE CONTENT\",\"description\":\"Large white reading area built from multiple narrow paragraphs of small gray body text, using generous margins and consistent left alignment for a formal company-profile or business communication aesthetic.\"},{\"section\":\"SIGNATURE BLOCK\",\"description\":\"Lower-left signature area includes a handwritten-style signature mark, a bold printed name and a compact title or department line.\"},{\"section\":\"BOTTOM ACCENT RULE\",\"description\":\"A full-width teal horizontal strip separates the white document area from the dark contact footer.\"},{\"section\":\"CONTACT FOOTER\",\"description\":\"Full-width deep slate footer contains three evenly spaced contact groups with circular teal or white icons, compact labels, phone or web details and a small company address block.\"}],\"assets_links\":[{\"type\":\"font\",\"name\":\"Montserrat\",\"url\":\"https://fonts.google.com/specimen/Montserrat\",\"license\":\"Free Commercial License\"},{\"type\":\"font\",\"name\":\"Open Sans\",\"url\":\"https://fonts.google.com/specimen/Open+Sans\",\"license\":\"Apache License 2.0\"},{\"type\":\"font\",\"name\":\"Allura\",\"url\":\"https://fonts.google.com/specimen/Allura\",\"license\":\"Free Commercial License\"},{\"type\":\"icon_set\",\"name\":\"Font Awesome Free\",\"url\":\"https://fontawesome.com/download\",\"license\":\"Free License\"},{\"type\":\"icon\",\"name\":\"Phone Contact Icon\",\"query\":\"Font Awesome phone\",\"glyph\":\"\"},{\"type\":\"icon\",\"name\":\"Globe Website Icon\",\"query\":\"Font Awesome globe\",\"glyph\":\"\"},{\"type\":\"icon\",\"name\":\"Location Address Icon\",\"query\":\"Font Awesome location-dot\",\"glyph\":\"\"},{\"type\":\"vector\",\"name\":\"Minimal Corporate Circular Logo Reference\",\"url\":\"https://www.freepik.com/search?query=minimal%20corporate%20logo\",\"license\":\"Verify license before commercial use\"}],\"layer_tree\":[{\"folder\":\"01_BLEED_&_GUIDES (Locked, Non-Printing)\",\"layers\":[{\"name\":\"3mm Bleed Boundary\",\"type\":\"guide\",\"icon\":\"🔲\"},{\"nam