ess%20logo\"},{\"type\":\"vector\",\"name\":\"Contact Information Icons\",\"query\":\"Font Awesome phone envelope globe location icons\",\"url\":\"https://fontawesome.com/icons\"},{\"type\":\"texture\",\"name\":\"Subtle White Paper Texture\",\"query\":\"Minimal white paper texture\",\"url\":\"https://unsplash.com/s/photos/white-paper-texture\"}],\"layer_tree\":[{\"folder\":\"01_BLEED_&_GUIDES (Locked, Non-Printing)\",\"layers\":[{\"name\":\"Trim Line Margin (210x297mm)\",\"type\":\"guide\",\"icon\":\"🔲\"},{\"name\":\"Bleed Area (3mm All Sides)\",\"type\":\"guide\",\"icon\":\"🔲\"},{\"name\":\"Safe Zone Margin (5mm Inside Trim)\",\"type\":\"guide\",\"icon\":\"🔲\"},{\"name\":\"Header and Footer Alignment Guides\",\"type\":\"guide\",\"icon\":\"🔲\"}]},{\"folder\":\"02_TEXT_CONTENT\",\"layers\":[{\"name\":\"Logo Text - LOGO HERE\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Logo Tagline - Slogan Goes Here\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Company Address Text\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Company Phone and Email Text\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Company Website Text\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Recipient Name Text\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Letter Greeting and Subject Text\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Letter Date Text\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Body Paragraphs 01-05\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Signature Script Text\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Sender Name and Job Title\",\"type\":\"text\",\"icon\":\"📁\"}]},{\"folder\":\"03_LOGO_&_ICONS\",\"layers\":[{\"name\":\"Abstract Circular Brand Logo\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Logo Inner Geometric Accent\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Phone Icon\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Email Icon\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Website Icon\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Location Icon\",\"type\":\"vector\",\"icon\":\"📁\"}]},{\"folder\":\"04_IMAGE_PLACEHOLDERS (Smart Objects)\",\"layers\":[{\"name\":\"Optional Paper Texture - Replace Here\",\"type\":\"smart_object\",\"icon\":\"🖼️\"},{\"name\":\"Optional Company Logo - Replace Here\",\"type\":\"smart_object\",\"icon\":\"🖼️\"}]},{\"folder\":\"05_VECTOR_SHAPES\",\"layers\":[{\"name\":\"Top Header Charcoal Rectangle\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Left Cyan Vertical Header Accent\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Logo Cyan Circle Background\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Logo Geometric Linework\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Contact Information Alignment Block\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Bottom Cyan Footer Strip\",\"type\":\"shape\",\"icon\":\"🎨\"}]},{\"folder\":\"06_BACKGROUND\",\"layers\":[{\"name\":\"A4 Paper Base - White\",\"type\":\"solid_color\",\"icon\":\"🎨\"},{\"name\":\"Optional Subtle Paper Texture Overlay\",\"type\":\"texture\",\"icon\":\"🎨\"}]},{\"folder\":\"07_PRINT_FINISHING\",\"layers\":[{\"name\":\"CMYK Color Proof Overlay\",\"type\":\"adjustment\",\"icon\":\"📁\"},{\"name\":\"Overprint and Rich Black Check\",\"type\":\"adjustment\",\"icon\":\"📁\"},{\"name\":\"Final Export Notes - PDF/X-1a\",\"type\":\"note\",\"icon\":\"📁\"}]}]}'),
