(637, 'Corporate Company Letterhead Design PSD Template', '', '[]', '[\"uploads\\/task_images\\/task_6a929fb5c86ec.webp\"]', '[]', '[\"https://www.magnific.com/free-vector/letterhead-template-with-various-colors_6417378.htm#fromView=author&page=8&position=33&uuid=9901dd1d-af31-4d42-9940-8f9678e099fe\"]', 1, NULL, 'Graphic Design', 1, 'Medium', 'Unassigned', 0, 'Stopped', NULL, 0, NULL, '2026-08-29 09:01:13', '2026-08-29 09:01:13', NULL, NULL, NULL, '2026-08-29', NULL, NULL, NULL, NULL, NULL, NULL, 'agentic', '{\"task_title\":\"Corporate Company Letterhead Design PSD Template\",\"doc_format\":\"A4 Print Letterhead\",\"resolution_mode\":\"300 DPI • CMYK\",\"dimensions\":\"210 x 297 mm\",\"bleed_margin\":\"3 mm All Margins\",\"color_palette\":[{\"name\":\"Brand Red\",\"hex\":\"#ED1C24\"},{\"name\":\"Deep Red\",\"hex\":\"#C8102E\"},{\"name\":\"Charcoal Text\",\"hex\":\"#333333\"},{\"name\":\"Secondary Gray\",\"hex\":\"#666666\"},{\"name\":\"Light Gray\",\"hex\":\"#D9D9D9\"},{\"name\":\"Paper White\",\"hex\":\"#FFFFFF\"}],\"typography\":[{\"font\":\"Montserrat\",\"weights\":\"600, 700\",\"usage\":\"Company name, logo lockup, signature name and footer labels\"},{\"font\":\"Arial\",\"weights\":\"400, 700\",\"usage\":\"Letter body copy, address details, date line and contact information\"},{\"font\":\"Open Sans\",\"weights\":\"400, 600\",\"usage\":\"Optional substitute for body copy, microtext and footer contact details\"}],\"layout_breakdown\":[{\"section\":\"HEADER BRANDING\",\"description\":\"Clean white header with a full-width red horizontal accent bar positioned near the top edge. The left side uses an angled red wedge, followed by a red hexagonal outline logo mark and compact company-name lockup reading Company logo with the subtitle VISUAL ART & DESIGN.\"},{\"section\":\"HEADER RIGHT ACCENT\",\"description\":\"A long red horizontal block extends across the upper-right portion of the page and begins with a diagonal cut, creating a sharp corporate geometric transition.\"},{\"section\":\"DOCUMENT META\",\"description\":\"Small gray date text is aligned to the upper-right of the letter content area, approximately level with the opening paragraph.\"},{\"section\":\"LETTER BODY\",\"description\":\"Single-column business correspondence layout with a short recipient or salutation line, multiple compact paragraphs, generous white space, and restrained dark-gray typography.\"},{\"section\":\"SIGNATURE BLOCK\",\"description\":\"Lower-left handwritten-style signature graphic above the printed sender name and role details, separated from the body by clear vertical spacing.\"},{\"section\":\"FOOTER CONTACT BAR\",\"description\":\"Bottom white footer area with a red geometric wedge on the left and three compact contact groups across the lower margin. Each group uses a small red or dark icon followed by phone, website/email, and address details.\"},{\"section\":\"FOOTER GEOMETRY\",\"description\":\"The lower-left red accent mirrors the header treatment with an angled inner edge and horizontal red block, maintaining a consistent visual identity across the page.\"}],\"assets_links\":[{\"type\":\"font\",\"name\":\"Montserrat\",\"url\":\"https://fonts.google.com/specimen/Montserrat\",\"license\":\"Open Font License; free commercial use\"},{\"type\":\"font\",\"name\":\"Open Sans\",\"url\":\"https://fonts.google.com/specimen/Open+Sans\",\"license\":\"Apache License 2.0; free commercial use\"},{\"type\":\"font\",\"name\":\"Arial\",\"url\":\"https://docs.microsoft.com/en-us/typography/font-list/arial\",\"license\":\"System font; verify licensing for redistribution\"},{\"type\":\"icon\",\"name\":\"Phone, globe and location contact icons\",\"url\":\"https://fontawesome.com/icons\",\"license\":\"Use according to Font Awesome license terms\"},{\"type\":\"vector\",\"name\":\"Hexagonal visual-art logo mark\",\"url\":\"https://www.freepik.com/search?query=hexagon%20logo%20vector\",\"license\":\"Verify asset license before production use\"},{\"type\":\"vector\",\"name\":\"Corporate geometric red banner shapes\",\"url\":\"https://www.freepik.com/search?query=corporate%20geometric%20red%20shapes\",\"license\":\"Verify asset license before production use\"},{\"type\":\"graphic\",\"name\":\"Handwritten signature placeholder\",\"url\":\"https://www.freepik.com/search?query=handwritten%20signature%20vector\",\"license\":\"Verify asset license before production use\"}],\"layer_tree\":[{\"folder\":\"01_BLEED_&_GUIDES (Locked, Non-Printing)\",\"layers\":[{\"name\":\"Trim Line Margin (210x297mm)\",\"type\":\"guide\",\"icon\":\"🔲\"},{\"name\":\"Bleed Area (3mm All Sides)\",\"type\":\"guide\",\"icon\":\"🔲\"},{\"name\":\"Safe Zone Margin (5mm Inside Trim)\",\"type\":\"guide\",\"icon\":\"🔲\"},{\"name\":\"Header and Footer Alignment Guides\",\"type\":\"guide\",\"icon\":\"🔲\"}]},{\"folder\":\"02_TEXT_CONTENT\",\"layers\":[{\"name\":\"Company Name - Company logo\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Company Descriptor - VISUAL ART & DESIGN\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Date Text - September 2022\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Letter Salutation / Recipient Line\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Letter Body Paragraphs\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Signature Printed Name\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Signature Job Title\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Footer Phone and Fax Details\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Footer Website and Email Details\",\"type\":\"text\",\"icon\":\"📁\"},{\"name\":\"Footer Street Address\",\"type\":\"text\",\"icon\":\"📁\"}]},{\"folder\":\"03_LOGO_&_ICONS\",\"layers\":[{\"name\":\"Hexagonal Brand Logo Mark\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Header Logo Lockup\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Phone Icon\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Website / Globe Icon\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Location / Address Icon\",\"type\":\"vector\",\"icon\":\"📁\"},{\"name\":\"Signature Graphic\",\"type\":\"smart_object\",\"icon\":\"🖼️\"}]},{\"folder\":\"04_VECTOR_SHAPES\",\"layers\":[{\"name\":\"Top Left Red Angled Wedge\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Top Right Red Horizontal Banner\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Top Right Diagonal Banner Cut\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Bottom Left Red Footer Banner\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Bottom Left Diagonal Footer Cut\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Footer Contact Icon Containers\",\"type\":\"shape\",\"icon\":\"🎨\"}]},{\"folder\":\"05_DOCUMENT_CONTENT\",\"layers\":[{\"name\":\"Letter Body Text Frame\",\"type\":\"text_frame\",\"icon\":\"📄\"},{\"name\":\"Date and Alignment Area\",\"type\":\"shape\",\"icon\":\"🎨\"},{\"name\":\"Signature Placement Area\",\"type\":\"shape\",\"icon\":\"🎨\"}]},{\"folder\":\"06_BACKGROUND\",\"layers\":[{\"name\":\"Paper White Base\",\"type\":\"solid_color\",\"icon\":\"🎨\"},{\"name\":\"Subtle White Print Texture\",\"type\":\"effect\",\"icon\":\"✨\"}]},{\"folder\":\"07_OUTPUT_NOTES\",\"layers\":[{\"name\":\"CMYK Print Proof\",\"type\":\"note\",\"icon\":\"📝\"},{\"name\":\"Replace Logo Placeholder\",\"type\":\"note\",\"icon\":\"📝\"},{\"name\":\"Update Letter Copy and Contact Information\",\"type\":\"note\",\"icon\":\"📝\"}]}]}'),
